use vstd::prelude::*;

verus! {

fn reverse(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int|
            0 <= i < result.len() ==> result[i] == a[(result.len() - 1 - i) as int],
{
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            i <= n,
            result.len() == i,
            forall|k: int|
                0 <= k < i ==> result[k] == a[(n - 1 - k) as int],
        decreases n - i,
    {
        // Safe because i < n, so (n-1-i) is in-bounds.
        let idx = n - 1 - i;
        result.push(a[idx]);
        i = i + 1;
    }

    result
}

}

